-- P05: limit, expiry, plan and payment proofs; runner wraps BEGIN/ROLLBACK.
\set ON_ERROR_STOP 1
SET client_min_messages = warning;
CREATE SCHEMA t;
CREATE TABLE t.results(name text,ok boolean,detail text);
CREATE TABLE t.shops(slug text,result jsonb);
CREATE TABLE t.payments(id uuid);
CREATE FUNCTION t.expect(n text,b boolean,d text DEFAULT NULL) RETURNS void LANGUAGE sql AS $$ INSERT INTO t.results VALUES(n,b,d) $$;
CREATE FUNCTION t.error(n text,q text,c text,expected jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$
DECLARE d text; BEGIN
 BEGIN EXECUTE q; PERFORM t.expect(n,false,'no error');
 EXCEPTION WHEN others THEN GET STACKED DIAGNOSTICS d=PG_EXCEPTION_DETAIL; PERFORM t.expect(n,split_part(SQLERRM,':',1)=c AND (expected IS NULL OR d::jsonb=expected),SQLERRM||' '||d); END;
END $$;
CREATE FUNCTION t.as_user(u text,o uuid DEFAULT NULL) RETURNS void LANGUAGE sql AS $$ SELECT set_config('request.jwt.claim.sub',COALESCE(u,''),false),set_config('app.org_id','',false),set_config('request.headers',CASE WHEN o IS NULL THEN '{}' ELSE json_build_object('x-org-id',o)::text END,false) $$;
CREATE FUNCTION t.org(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'organization_id')::uuid FROM t.shops WHERE slug=s $$;
CREATE FUNCTION t.emp(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'owner_employee_id')::uuid FROM t.shops WHERE slug=s $$;
CREATE FUNCTION t.branch(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'branch_id')::uuid FROM t.shops WHERE slug=s $$;
CREATE FUNCTION t.permission(k text) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT app.require_permission(k) $$;
GRANT USAGE ON SCHEMA t TO authenticated;
GRANT SELECT ON t.shops TO authenticated;
GRANT INSERT ON t.results TO authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA t TO authenticated;
SELECT t.as_user('f0000000-0000-0000-0000-000000000001');
INSERT INTO t.shops SELECT s,public.admin_provision_organization(s,s,p,'Owner',s||'@example.com',NULL,'Main',h,now()+interval '1 day') FROM (VALUES('p05-starter','starter',repeat('a',64)),('p05-retail','retail',repeat('b',64)),('p05-unlimited','enterprise',repeat('c',64))) v(s,p,h);
SELECT t.error('starter branch limit',$q$INSERT INTO public.branches(organization_id,code,name) VALUES(t.org('p05-starter'),'B2','Extra')$q$,'PLAN_LIMIT_REACHED','{"resource":"branches","limit":1,"used":1}');
INSERT INTO public.branches(organization_id,code,name,archived_at) VALUES(t.org('p05-starter'),'ARCH','Archived',now());
SELECT t.error('unarchive branch limit',$q$UPDATE public.branches SET archived_at=NULL WHERE organization_id=t.org('p05-starter') AND code='ARCH'$q$,'PLAN_LIMIT_REACHED');
INSERT INTO public.employees(organization_id,full_name,role) SELECT t.org('p05-starter'),'Pending '||i,'CASHIER' FROM generate_series(1,4) i;
SELECT t.error('pending employees count as users',$q$INSERT INTO public.employees(organization_id,full_name,role) VALUES(t.org('p05-starter'),'sixth','CASHIER')$q$,'PLAN_LIMIT_REACHED','{"resource":"users","limit":5,"used":5}');
UPDATE public.employees SET is_active=false WHERE organization_id=t.org('p05-starter') AND full_name='Pending 1';
INSERT INTO public.employees(organization_id,full_name,role) VALUES(t.org('p05-starter'),'replacement','CASHIER');
SELECT t.expect('deactivated employee frees seat',(app.plan_usage(t.org('p05-starter'))#>>'{users,used}')::int=5);
SELECT t.error('reactivation cannot exceed user limit',$q$UPDATE public.employees SET is_active=true WHERE organization_id=t.org('p05-starter') AND full_name='Pending 1'$q$,'PLAN_LIMIT_REACHED');
INSERT INTO public.devices(organization_id,branch_id,name) SELECT t.org('p05-starter'),t.branch('p05-starter'),'D'||i FROM generate_series(1,2)i;
SELECT t.error('device limit',$q$INSERT INTO public.devices(organization_id,branch_id,name) VALUES(t.org('p05-starter'),t.branch('p05-starter'),'D3')$q$,'PLAN_LIMIT_REACHED','{"resource":"devices","limit":2,"used":2}');
INSERT INTO public.branches(organization_id,code,name) SELECT t.org('p05-unlimited'),'B'||i,'Extra'||i FROM generate_series(2,10)i;
SELECT t.expect('unlimited accepts ten branches',(app.plan_usage(t.org('p05-unlimited'))#>>'{branches,used}')::int=10);
SELECT t.expect('retail includes installments',app.org_has_module(t.org('p05-retail'),'installments'));
SELECT t.expect('starter excludes installments',NOT app.org_has_module(t.org('p05-starter'),'installments'));
INSERT INTO auth.users(id,email) VALUES('a0500000-0000-4000-8000-000000000001','p05-starter@example.com');
SELECT public.accept_invite(repeat('a',64),'a0500000-0000-4000-8000-000000000001');
UPDATE public.organizations SET subscription_start=NULL,subscription_end=app.org_today(id) WHERE id=t.org('p05-starter');
SELECT t.expect('end day inclusive',NOT app.org_is_expired(t.org('p05-starter')));
UPDATE public.organizations SET subscription_end=app.org_today(id)-1 WHERE id=t.org('p05-starter');
SELECT t.as_user('a0500000-0000-4000-8000-000000000001',t.org('p05-starter'));
SET LOCAL ROLE authenticated;
SELECT t.error('expired write denied',$q$SELECT t.permission('sale.create')$q$,'SUBSCRIPTION_EXPIRED');
SELECT t.expect('expired export allowed',t.permission('export.data') IS NOT NULL);
SELECT t.expect('expired RLS read visible',(SELECT count(*)=2 FROM public.branches));
SELECT t.expect('expired owner can select shop',(SELECT count(*)=1 FROM public.my_shops()));
SELECT t.expect('expired status correct',public.get_subscription_status()->>'state'='expired' AND (public.get_subscription_status()->>'read_only')::boolean AND (public.get_subscription_status()->>'days_left')::int=-1);
SELECT public.auth_record_login();
SELECT t.expect('expired session still valid',(SELECT refusal IS NULL FROM public.session_context()));
SELECT t.error('owner cannot change plan',format('SELECT public.admin_change_plan(%L,''retail'',''x'')',t.org('p05-starter')),'SUPER_ADMIN_REQUIRED');
SELECT t.error('owner cannot set dates',format('SELECT public.admin_set_subscription_dates(%L,CURRENT_DATE,NULL,''x'')',t.org('p05-starter')),'SUPER_ADMIN_REQUIRED');
SELECT t.error('owner cannot get platform subscription',format('SELECT public.admin_get_subscription(%L)',t.org('p05-starter')),'SUPER_ADMIN_REQUIRED');
SELECT t.error('owner cannot record payment',format('SELECT public.admin_record_subscription_payment(%L,500,CURRENT_DATE,CURRENT_DATE,NULL,true,gen_random_uuid())',t.org('p05-starter')),'SUPER_ADMIN_REQUIRED');
SELECT t.error('owner cannot list shops',$q$SELECT public.admin_list_organizations()$q$,'SUPER_ADMIN_REQUIRED');
RESET ROLE;
SELECT t.as_user('f0000000-0000-0000-0000-000000000001');
INSERT INTO public.branches(organization_id,code,name) VALUES(t.org('p05-retail'),'B2','Second');
SELECT t.error('downgrade lists exceeded resource',format('SELECT public.admin_change_plan(%L,''starter'',''test'')',t.org('p05-retail')),'PLAN_DOWNGRADE_BLOCKED','[{"resource":"branches","limit":1,"used":2}]');
UPDATE public.branches SET archived_at=now() WHERE organization_id=t.org('p05-retail') AND code='B2';
SELECT public.admin_change_plan(t.org('p05-retail'),'starter','test');
SELECT t.expect('downgrade audit',(SELECT count(*)=1 FROM public.audit_log WHERE organization_id=t.org('p05-retail') AND action='subscription.plan_changed' AND super_admin_id IS NOT NULL));
SELECT t.error('dates order',format('SELECT public.admin_set_subscription_dates(%L,CURRENT_DATE,CURRENT_DATE-1,''test'')',t.org('p05-starter')),'DATES_INVALID');
SELECT t.error('reason required',format('SELECT public.admin_change_plan(%L,''retail'','' '')',t.org('p05-starter')),'REASON_REQUIRED');
SELECT t.error('non-finite payment denied',format('SELECT public.admin_record_subscription_payment(%L,''NaN''::numeric,CURRENT_DATE,CURRENT_DATE,NULL,true,gen_random_uuid())',t.org('p05-starter')),'VALIDATION_FAILED');
INSERT INTO t.payments SELECT public.admin_record_subscription_payment(t.org('p05-starter'),500.25,app.org_today(t.org('p05-starter')),app.org_today(t.org('p05-starter'))+30,'manual',true,'a0500000-0000-4000-8000-000000000002');
SELECT t.expect('payment replay same id',public.admin_record_subscription_payment(t.org('p05-starter'),500.25,CURRENT_DATE,CURRENT_DATE+30,'manual',true,'a0500000-0000-4000-8000-000000000002')=(SELECT id FROM t.payments));
SELECT t.expect('one decimal payment and platform actor',(SELECT count(*)=1 AND bool_and(amount=500.25 AND recorded_by_admin='f0000000-0000-0000-0000-000000000001') FROM public.subscription_payments WHERE organization_id=t.org('p05-starter')));
SELECT t.expect('payment sets start and extends end',(SELECT subscription_start=app.org_today(id) AND subscription_end=app.org_today(id)+30 FROM public.organizations WHERE id=t.org('p05-starter')));
SELECT t.expect('payment single audit',(SELECT count(*)=1 FROM public.audit_log WHERE organization_id=t.org('p05-starter') AND action='subscription.payment_recorded'));
SELECT t.expect('platform money as string',jsonb_typeof(public.admin_get_subscription(t.org('p05-starter'))#>'{payments,0,amount}')='string');
SELECT t.expect('anon denied all public P05 functions',NOT EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('admin_change_plan','admin_set_subscription_dates','admin_record_subscription_payment','admin_get_subscription','get_subscription_status','require_module') AND has_function_privilege('anon',oid,'EXECUTE')));
SELECT t.expect('helpers have no authenticated grants',NOT EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='app'::regnamespace AND proname IN('org_is_expired','plan_usage','org_has_module','require_module','enforce_plan_limit') AND has_function_privilege('authenticated',oid,'EXECUTE')));
SELECT t.as_user('a0500000-0000-4000-8000-000000000001',t.org('p05-starter'));
SELECT t.expect('renewed write allowed',app.require_permission('sale.create') IS NOT NULL);
SELECT t.expect('active status',public.get_subscription_status()->>'state'='active');
UPDATE public.organizations SET subscription_end=app.org_today(id)+10 WHERE id=t.org('p05-starter');
SELECT t.expect('expiring status and usage',public.get_subscription_status()->>'state'='expiring' AND (public.get_subscription_status()->>'days_left')::int=10 AND (public.get_subscription_status()#>>'{usage,users,used}')::int=5);
UPDATE public.organizations SET subscription_end=NULL WHERE id=t.org('p05-starter');
SELECT t.expect('no end not expired',NOT app.org_is_expired(t.org('p05-starter')) AND public.get_subscription_status()->>'state'='no_end' AND public.get_subscription_status()->>'days_left' IS NULL);
SELECT t.error('module helper refuses absent module',$q$SELECT public.require_module('installments')$q$,'MODULE_NOT_IN_PLAN');
SELECT t.as_user(NULL);
SELECT t.error('no session status denied',$q$SELECT public.get_subscription_status()$q$,'NOT_AN_EMPLOYEE');
SELECT name,ok,detail FROM t.results WHERE NOT COALESCE(ok,false);
SELECT count(*) FILTER(WHERE ok) passed,count(*) FILTER(WHERE NOT COALESCE(ok,false)) failed FROM t.results;

